"use strict";
let visitMode='phone',pcTab='browser',pcHistory=[],phoneWebLayout='mobile';
try{if(localStorage.getItem('olddays-visit-mode')==='pc')visitMode='pc';}catch{}
const pcBaseEntrance=renderPhoneEntrance,pcBaseWorkbench=renderWorkbench,pcBaseAllowed=phoneAppAllowed;
function visitSwitcher(){return `<nav class="visit-switcher" aria-label="游玩方式"><button data-visit-mode="phone" aria-pressed="${visitMode==='phone'}">▣ 手机游玩</button><button data-visit-mode="pc" aria-pressed="${visitMode==='pc'}">▤ 电脑上网</button></nav>`;}
renderPhoneEntrance=function(){return visitSwitcher()+(visitMode==='pc'?renderPcWorkbench():pcBaseEntrance());};
renderWorkbench=function(){return visitSwitcher()+(visitMode==='pc'?renderPcWorkbench():pcBaseWorkbench());};
phoneAppAllowed=function(app){return visitMode==='pc'?app!=='java':pcBaseAllowed(app);};
function renderPcWorkbench(){deskEntered=true;if(phoneState.app==='home')phoneState.app='browser';const tabs=[['browser','Internet Explorer','e'],['qq','QQ消息','QQ'],['community','校园BBS','坛'],['sms','短信备份','✉'],['photos','我的图片','▧'],['music','音乐播放器','♪'],['anime','动漫社','漫'],['campus','失物档案','?']];return `<section class="pc-desktop"><aside class="pc-desktop-icons">${tabs.map(([id,t,i])=>`<button data-pc-app="${id}"><b>${i}</b>${t}</button>`).join('')}</aside><article class="pc-window"><header class="pc-titlebar"><span>▣ ${escapeHTML(tabs.find(t=>t[0]===phoneState.app)?.[1]||'旧日互联网')} — 旧日电脑</span><div><button data-visit-mode="phone" aria-label="返回手机游玩">▣</button></div></header><nav class="pc-menubar">文件(F)　编辑(E)　查看(V)　收藏(A)　工具(T)　帮助(H)</nav><div class="pc-toolbar"><button data-pc-back>‹ 后退</button><button data-pc-app="browser">⌂ 主页</button><span>地址(D)</span><input aria-label="电脑地址或站内搜索" data-pc-address value="${escapeHTML(deskWebsite?.url&&phoneState.app==='browser'&&ucContent==='web'?deskWebsite.url:'olddays://'+phoneState.app)}"><button data-pc-go>转到</button></div><nav class="pc-tabs">${tabs.map(([id,t])=>`<button data-pc-app="${id}" aria-pressed="${phoneState.app===id}">${t}</button>`).join('')}</nav><div id="device-viewport" class="pc-content">${phoneScreen()}</div><footer class="pc-status">完成　｜　${date}　｜　旧日电脑 · 本机游玩</footer></article><footer class="pc-taskbar"><button data-pc-app="browser">▦ 开始</button><span>旧日互联网</span><time>20:04</time></footer></section>`;}
const pcPhoneBrowser=phoneUCMarkup;
phoneUCMarkup=function(){if(visitMode!=='pc')return pcPhoneBrowser();if(typeof campusPanel!=='undefined'&&campusPanel)return campusMarkup();if(typeof mysteryPanel!=='undefined'&&mysteryPanel)return mysteryMarkup();return `<section class="pc-browser-page">${typeof campusBrowserClue==='function'?campusBrowserClue():''}${typeof mystery!=='undefined'&&mystery.started&&/旧城|失物|夏末/.test(ucQuery)?mysteryButton('uc','旧城失物招领 / 案件缓存'):''}${ucContent?`<button data-uc-back>‹ 返回导航</button>${ucRenderedContent()}`:`<header><small>PERSONAL INTERNET / ${year()}</small><h1>欢迎来到，那个还要拨号的晚上。</h1><p>打开门户、找一张旧网页，或者看看同学有没有回消息。</p></header><form data-uc-search><input name="query" aria-label="电脑站内搜索" placeholder="输入线索、站点或内容" value="${escapeHTML(ucQuery)}"><button>搜索</button></form><div class="pc-page-columns"><section><h2>今日校园</h2><button data-pc-app="campus">失物招领：这是谁的手机？</button><button data-pc-app="anime">放学动漫社 · 追番与讨论</button><button data-pc-app="community">校园BBS · 旧楼七点十七</button></section><section><h2>网址收藏夹</h2>${ucWebsiteDirectory()}</section></div>`}</section>`;};
const pcArchiveMarkup=phoneWebsiteMarkup;
phoneWebsiteMarkup=function(){return `<nav class="web-layout-toggle" aria-label="网页显示方式"><button data-web-layout="mobile" aria-pressed="${phoneWebLayout==='mobile'}">手机版</button><button data-web-layout="desktop" aria-pressed="${phoneWebLayout==='desktop'}">PC版网页</button></nav><div class="web-layout-${visitMode==='pc'?'desktop':phoneWebLayout}">${pcArchiveMarkup()}</div>`;};
function setVisitMode(mode){if(!['phone','pc'].includes(mode))return;visitMode=mode;document.body.classList.remove('pocket-expanded','pocket-landscape','exploration-open');try{localStorage.setItem('olddays-visit-mode',mode);}catch{}deskEntered=mode==='pc';phoneState.app='home';if(mode==='pc'){phoneState.app='browser';ucContent='';}navigate({type:'home'},false);}
function pcOpenApp(app){if(!['browser','qq','community','sms','photos','music','anime','campus'].includes(app))return;if(phoneState.app!==app)pcHistory.push(phoneState.app);phoneState.app=app;pcTab=app;campusPanel='';mysteryPanel='';navigate({type:'home'},false);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-visit-mode],[data-pc-app],[data-pc-go],[data-pc-back],[data-web-layout]');if(!b)return;e.preventDefault();if(b.dataset.visitMode)return setVisitMode(b.dataset.visitMode);if(b.dataset.pcApp)return pcOpenApp(b.dataset.pcApp);if(b.dataset.webLayout){phoneWebLayout=b.dataset.webLayout==='desktop'?'desktop':'mobile';return refreshPhone();}if(b.hasAttribute('data-pc-back')){const app=pcHistory.pop()||'browser';phoneState.app=app;campusPanel='';mysteryPanel='';return navigate({type:'home'},false);}if(b.hasAttribute('data-pc-go')){const value=document.querySelector('[data-pc-address]').value.trim();const site=siteCatalog.flatMap(g=>g.sites).find(s=>s.url===value||s.url.replace(/^https?:\/\//,'')===value.replace(/^https?:\/\//,''));phoneState.app='browser';if(site){deskWebsite=site;ucContent='web';}else{ucQuery=value;ucContent='';}navigate({type:'home'},false);}});
document.addEventListener('keydown',e=>{if(e.target.matches?.('[data-pc-address]')&&e.key==='Enter'){e.preventDefault();document.querySelector('[data-pc-go]')?.click();}});
const pcSelectBase=phoneSelectApp,pcOpenBase=openPhoneLab;
phoneSelectApp=function(app){if(visitMode==='pc'&&app==='home'){phoneState.app='browser';ucContent='';return navigate({type:'home'},false);}return pcSelectBase(app);};
openPhoneLab=function(app){if(visitMode==='pc'&&app){if(!phoneAppAllowed(app)){toast('电脑窗口未提供该模拟器');return;}phoneState.app=app;deskEntered=true;return navigate({type:'home'},false);}return pcOpenBase(app);};
